window.RP_SESSION={"id":"S-bfa87a29c3e4","messages":[{"id":"RP-III-0009384","time":"2026-01-23T22:42:00+09:00","room":"RP III","name":"진저브레이브","profile":"진저브레이브","identity":"reviewed","type":"dialogue","body":"——————————————\n(\"형! 오늘도 일하러 가는거야? 요즘 매일 가잖아..!\")\n\n(\"오빠..엄마 아빠는 언제쯤 오는걸까..?\")\n\n(\"꼭..살아 돌아와야해..알겠지?\")\n\n\"걱정마! 무사히 돌아올테니까!\"\n\n[..기억이 나지 않는다. 아마 그게 마지막이였겠지.]\n——————————————\n\n\n[두려워할 용기]\n\n\"....어라.\"\n\n{꽃들이 가득 심어져있는 길드의 뒷편에서 일어난 진저. 또 꿈을 꾸었는지,잔뜩 뒤척인체 흙더미가되어 깨어납니다. 흠 소리를 내며,주변을 두리번거리다가 기억이 찔러오는 머리를 붙잡으며 고통을 호소하다 다시 주저앉아버리는 그.\n\n익숙하지가 않습니다. 삶을 도망치듯 살아왔고 책임을 짊어진체 굽은 허리로 생을 보내왔으면서,죽어가던 순간에야 비로소 웃을수 있었으니까요. 하지만,동시에 가슴이 아파옵니다. 이렇게 자신은 책임에서 벗어났지만 자신이 부양하던 가족들을 두고온게 마음에 걸리니말이죠.}\n\n\"...흐끅..흐윽..\"\n\n{무언갈 잃는건 이렇게 참혹한 고통이","characters":["P-11b5c9c4a5f1"]},{"id":"RP-III-0009385","time":"2026-01-23T22:42:00+09:00","room":"RP III","name":"진저브레이브","profile":"진저브레이브","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-11b5c9c4a5f1"]},{"id":"RP-III-0009386","time":"2026-01-23T22:42:00+09:00","room":"RP III","name":"진저브레이브","profile":"진저브레이브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-11b5c9c4a5f1"]},{"id":"RP-III-0009387","time":"2026-01-23T22:42:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
